function art(p){if(p.id==='after-hours'&&!p.image)return `<img class="custom-cover" src="after-hours/cover.svg" alt="After Hours — workplace departure support in Noida" loading="lazy">`;if(p.id==='occasio'&&!p.image)return `<img class="custom-cover" src="assets/occasio/cover.png" alt="OCCASIO event discovery and planning" loading="lazy">`;if(p.id==='aura'&&!p.image)return `<div class="aura-project-cover"><div class="aura-cover-copy"><span class="aura-cover-wordmark">aura<span>✳</span></span><strong>At home.<br><em>At ease.</em></strong><span class="aura-cover-description">A voice-assisted companion<br>for confidence and connection.</span></div><div class="aura-cover-photo"><img src="assets/aura/editorial-home.png" alt="Illustrative older woman enjoying time at home" loading="lazy"><span class="aura-cover-credit">AI-generated illustration</span></div><div class="aura-cover-card"><span>⌂</span><div><small>SUPPORT THAT FEELS LIKE HOME</small><b>Your space. Your rhythm.</b></div></div></div>`;if(p.id==='gluvia'&&!p.image)return `<img class="custom-cover gluvia-cover" src="assets/gluvia/frame-34.png" alt="GLUVIA — diabetes management ecosystem, original phone and watch designs" loading="lazy">`;if(p.image&&/^data:image\/(png|jpeg|webp|gif);base64,/.test(p.image))return `<img class="custom-cover" src="${p.image}" alt="${esc(p.title)} project cover">`;const scenes={orbit:`<div class="phone"><div class="phone-top"><b>orbit↗</b><span>● ●</span></div><h4>Hey, Alex ☀<br>Looking good.</h4><div class="mini-orbit">Your total balance<strong>€12,840<span style="font-size:11px">.00</span></strong></div><div class="mini-bars"><i></i><i></i><i></i><i></i><i></i></div><div class="phone-rule"></div>⌂　↗　◎　▦</div><div class="phone secondary-phone"><div class="phone-top"><b>← Your goals</b><span>＋</span></div><h4>Big plans.<br>Small steps.</h4><div class="ring">72%</div><div style="text-align:center">A place of your own.</div><div class="mini-pill">Keep it growing ↗</div></div>`,common:`<div class="common-poster"><small>A SPACE FOR ALL OF US. / 001</small><strong>common<br><em>ground.</em></strong><footer>GOOD THINGS HAPPEN WHEN WE COME TOGETHER. ↗</footer></div><div class="common-seal">LESS ME.<br>MORE WE.<br>✳</div>`,form:`<div class="browser-frame"><div class="browser-top"><b>form & field</b><span>Objects　Our story　Bag (0)</span></div><div class="form-content"><small style="font-size:6px;letter-spacing:1px">THOUGHTFULLY MADE. EVERYDAY LOVED.</small><h4>Objects with soul.<br><i>Spaces with meaning.</i></h4><div class="form-objects"><div class="vase"></div><div class="vase alt"></div></div></div></div>`,next:`<div class="strategy-board"><small style="font-size:8px;letter-spacing:1.5px">A FIELD GUIDE TO POSSIBLE FUTURES</small><h4>Less guessing.<br><em>More what-if.</em> ↗</h4><div class="notes"><div class="note"><b>01 ↗</b>Find the<br>right question.</div><div class="note"><b>02 ✳</b>Explore the<br>possibilities.</div><div class="note"><b>03 →</b>Make the<br>future tangible.</div></div></div>`};return `<div class="scene" aria-hidden="true">${scenes[p.theme]||scenes.orbit}</div>`}
