function renderForm(){let html='';if(tab==='profile'){html=field('Your name','name',data.name)+field('Availability','availability',data.availability)+field('Headline · first line','headline1',data.headline1)+field('Headline · second line','headline2',data.headline2)+field('Introduction','intro',data.intro,'textarea')+field('About you','about',data.about,'textarea')+field('Contact email','email',data.email,'email')}else{selected=Math.max(0,Math.min(selected,data.projects.length-1));const p=data.projects[selected];html=`<label class="field">Select a project<select id="projectSelect">${data.projects.map((p,i)=>`<option value="${i}" ${selected===i?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><div class="project-edit-actions"><button type="button" id="addProject">＋ Add</button><button type="button" id="moveProject" ${selected===0?'disabled':''}>↑ Move up</button><button type="button" id="deleteProject" ${!p?'disabled':''}>Delete</button></div>`;if(p)html+=field('Project title','title',p.title)+field('Short description','subtitle',p.subtitle)+`<label class="field">Discipline<select name="category"><option ${p.category==='UI / UX'?'selected':''}>UI / UX</option><option ${p.category==='Strategy'?'selected':''}>Strategy</option></select></label>`+field('Year','year',p.year)+field('Your role','role',p.role)+`<label class="field">Preview style<select name="theme">${['orbit','common','form','next'].map(t=>`<option value="${t}" ${p.theme===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Upload your project cover (PNG, JPG, WebP, GIF)<input type="file" id="coverUpload" accept="image/png,image/jpeg,image/webp,image/gif"></label>${p.image?'<button type="button" class="secondary" id="removeCover">Remove cover image</button>':''}<label class="field"><input style="display:inline;width:auto" type="checkbox" name="concept" ${p.concept?'checked':''}> Label as an illustrative concept</label>`+field('The question','challenge',p.challenge,'textarea')+field('The approach','approach',p.approach,'textarea')+field('The outcome','outcome',p.outcome,'textarea')};$('#editForm').innerHTML=html+'<span class="save-indicator">● Changes save automatically</span>';bindProjectControls()}
$('.editor-tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;tab=b.dataset.tab;document.querySelectorAll('.editor-tabs button').forEach(x=>x.classList.toggle('active',x===b));renderForm()};$('#editForm').onsubmit=e=>e.preventDefault();$('#editForm').addEventListener('input',e=>{if(!e.target.name)return;const target=tab==='profile'?data:data.projects[selected];target[e.target.name]=e.target.type==='checkbox'?e.target.checked:e.target.value;save();if(e.target.name==='title')$('#projectSelect').options[selected].textContent=e.target.value});
