function validate(v){if(!v||typeof v!=='object'||!Array.isArray(v.projects)||v.projects.length>100)return false;for(const k of ['name','availability','headline1','headline2','intro','about','email'])if(typeof v[k]!=='string')return false;return v.projects.every(p=>p&&['id','title','subtitle','category','year','theme','image','role','challenge','approach','outcome'].every(k=>typeof p[k]==='string')&&['UI / UX','Strategy'].includes(p.category)&&['orbit','common','form','next'].includes(p.theme)&&typeof p.concept==='boolean'&&(!p.image||/^data:image\/(png|jpeg|webp|gif);base64,/.test(p.image)))&&new Set(v.projects.map(p=>p.id)).size===v.projects.length}
