const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
const entranceObserver = new IntersectionObserver(entries => entries.forEach(entry => {
  if (entry.isIntersecting) { entry.target.classList.add('arrived'); entranceObserver.unobserve(entry.target); }
}), {threshold: .08});
function observeEntrances() {
  document.querySelectorAll('.project, .about > div, .footer-title').forEach(el => {
    el.classList.add('entrance'); entranceObserver.observe(el);
  });
}
function renderMotion() {
  document.body.dataset.palette = data.palette;
  const paused = data.motionPaused || reducedMotion.matches;
  document.body.classList.toggle('motion-paused', paused);
  $('#motionPause').textContent = paused ? '▶ Play motion' : 'Ⅱ Pause motion';
  $('#motionPause').setAttribute('aria-pressed', String(paused));
  $('#paletteToggle').textContent = data.palette === 'night' ? '◐ Lavender light' : '◐ After hours';
  $('#paletteToggle').setAttribute('aria-pressed', String(data.palette === 'night'));
  const projects = data.projects.slice(0, 8);
  const group = `<div class="motion-group">${projects.map(p => `<div class="motion-tile">${visual(p,false)}<span>${esc(p.title)} <i>↗</i></span></div>`).join('')}</div>`;
  $('#motionTrack').innerHTML = projects.length ? group + group : '<p>Add a project to bring this space to life.</p>';
}
$('#motionPause').onclick = () => {
  if (reducedMotion.matches) { toast('Motion is reduced by your device accessibility preference.'); return; }
  data.motionPaused = !data.motionPaused; save();
};
$('#paletteToggle').onclick = () => { data.palette = data.palette === 'night' ? 'lavender' : 'night'; save(); };
reducedMotion.addEventListener('change',renderMotion);
$('#projects').addEventListener('pointermove', e => {
  if (e.pointerType !== 'mouse' || data.motionPaused || reducedMotion.matches) return;
  const card = e.target.closest('.project'); if (!card) return;
  const r = card.getBoundingClientRect();
  card.style.setProperty('--tilt-x', `${-(e.clientY-r.top-r.height/2)/r.height*6}deg`);
  card.style.setProperty('--tilt-y', `${(e.clientX-r.left-r.width/2)/r.width*8}deg`);
});
$('#projects').addEventListener('pointerout', e => {
  const card = e.target.closest('.project');
  if (card && !card.contains(e.relatedTarget)) { card.style.setProperty('--tilt-x','0deg');card.style.setProperty('--tilt-y','0deg'); }
});
render();

document.querySelector('#projectDetail').addEventListener('click',e=>{const b=e.target.closest('[data-source-chapter]');if(!b)return;const i=Number(b.dataset.sourceChapter),c=gluviaOriginalChapters[i];document.querySelectorAll('[data-source-chapter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#source-count').textContent='ORIGINAL FRAME '+String(i+1).padStart(2,'0')+' / 14';$('#source-title').textContent=c.title;$('#source-desc').textContent=c.desc;});
document.querySelector('#gm-open').onclick=()=>document.querySelector('[data-id="gluvia"]').click();

const hqGluvia=[{"src": "assets/gluvia/original-00.png", "name": "Rectangle.png", "title": "Glucose monitor composition"}, {"src": "assets/gluvia/original-01.png", "name": "iPhone 16 Plus Dark-1.png", "title": "Daily overview"}, {"src": "assets/gluvia/original-02.png", "name": "iPhone 16 Plus Dark.png", "title": "Connected watch"}, {"src": "assets/gluvia/original-03.png", "name": "iPhone 16 Plus Light-1.png", "title": "AI coach"}, {"src": "assets/gluvia/original-04.png", "name": "iPhone 16 Plus Light-10.png", "title": "Meal details"}, {"src": "assets/gluvia/original-05.png", "name": "iPhone 16 Plus Light-11.png", "title": "Logbook"}, {"src": "assets/gluvia/original-06.png", "name": "iPhone 16 Plus Light-12.png", "title": "Sign up"}, {"src": "assets/gluvia/original-07.png", "name": "iPhone 16 Plus Light-13.png", "title": "Profile"}, {"src": "assets/gluvia/original-08.png", "name": "iPhone 16 Plus Light-14.png", "title": "Insights"}, {"src": "assets/gluvia/original-09.png", "name": "iPhone 16 Plus Light-2.png", "title": "Glucose statistics"}, {"src": "assets/gluvia/original-10.png", "name": "iPhone 16 Plus Light-3.png", "title": "Add meal"}, {"src": "assets/gluvia/original-11.png", "name": "iPhone 16 Plus Light-4.png", "title": "AI coach \u2014 alternate"}, {"src": "assets/gluvia/original-12.png", "name": "iPhone 16 Plus Light-5.png", "title": "Registration"}, {"src": "assets/gluvia/original-13.png", "name": "iPhone 16 Plus Light-6.png", "title": "My devices"}, {"src": "assets/gluvia/original-14.png", "name": "iPhone 16 Plus Light-7.png", "title": "Sign up \u2014 alternate"}, {"src": "assets/gluvia/original-15.png", "name": "iPhone 16 Plus Light-8.png", "title": "Medication \u2014 dark"}, {"src": "assets/gluvia/original-16.png", "name": "iPhone 16 Plus Light-9.png", "title": "Medication \u2014 light"}, {"src": "assets/gluvia/original-17.png", "name": "iPhone 16 Plus Light.png", "title": "Care circle"}];
function hqGallery(){return `<section class="hq-gallery"><span class="eyebrow">ORIGINAL FIGMA EXPORTS / ${hqGluvia.length} VIEWS</span><h3>The mobile experience</h3><p>Monitoring, daily context, and connected care. Select a mockup to inspect the original export.</p><div class="hq-grid">${hqGluvia.map((a,i)=>`<button data-hq="${i}"><img src="${a.src}" alt="${esc(a.title)} — original GLUVIA design" loading="lazy" decoding="async"><span>${esc(a.title)} ↗</span></button>`).join('')}</div></section>`}
const oldSourceView=gluviaSourceView;gluviaSourceView=()=>{const view=oldSourceView();return view.replace('<div class="source-study">',hqGallery()+'<div class="source-study">')};
const hqDialog=document.createElement('dialog');hqDialog.className='hq-lightbox';hqDialog.innerHTML='<button class="hq-close" aria-label="Close original mockup">×</button><h3></h3><div class="hq-image-scroll"><img alt=""></div><a target="_blank" rel="noopener">Open full-resolution PNG ↗</a>';document.body.append(hqDialog);hqDialog.querySelector('button').onclick=()=>hqDialog.close();hqDialog.addEventListener('click',e=>{if(e.target===hqDialog)hqDialog.close()});
function openHQ(i){const a=hqGluvia[i];hqDialog.classList.toggle('is-frame',a.src.includes('frame-')||a.src.includes('/aura/'));hqDialog.querySelector('h3').textContent=a.title;hqDialog.querySelector('img').src=a.src;hqDialog.querySelector('img').alt=a.title+' — unchanged original Figma export';hqDialog.querySelector('a').href=a.src;hqDialog.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-hq]');if(b)openHQ(Number(b.dataset.hq))});
(()=>{const root=document.querySelector('#hq-motion'),img=root.querySelector('img'),tabs=[...root.querySelectorAll('[data-hq-scene]')],scenes=[{i:1,title:'The day at a glance.',desc:'A single overview for glucose, daily context, and connected care.'},{i:9,title:'See the bigger picture.',desc:'Glucose trends and statistics, brought into focus.'},{i:10,title:'Make room for context.',desc:'Meals and everyday details sit alongside the numbers.'},{i:17,title:'Keep care connected.',desc:'A shared care circle for the people around you.'}];let active=0,auto=true,queued=false;
function show(n){active=n;const a=scenes[n];img.src=hqGluvia[a.i].src;img.alt=hqGluvia[a.i].title+' — original GLUVIA mockup';root.querySelector('h3').textContent=a.title;root.querySelector('.hq-scene-desc').textContent=a.desc;root.querySelector('[data-hq]').dataset.hq=a.i;tabs.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)));root.querySelector('.hq-counter').textContent='0'+(n+1)+' / 04'}
const pause=root.querySelector('.hq-pause');function mode(v){auto=v;pause.textContent=v?'Ⅱ Pause scroll story':'▶ Follow scroll story';pause.setAttribute('aria-pressed',String(!v))}tabs.forEach((b,i)=>b.onclick=()=>{mode(false);show(i)});pause.onclick=()=>{mode(!auto);update()};function update(){queued=false;const r=root.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/Math.max(1,root.offsetHeight-innerHeight)));root.style.setProperty('--story-progress',p*100+'%');if(auto&&!reducedMotion.matches&&!data.motionPaused){const n=Math.min(3,Math.floor(p*4));if(n!==active)show(n);root.style.setProperty('--story-y',Math.round((p-.5)*20)+'px')}else root.style.setProperty('--story-y','0px')};addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);show(0);update()})();

