watchTitles.forEach((title,i)=>hqGluvia.push({title:'Watch — '+title,src:["assets/gluvia/watch-00.png", "assets/gluvia/watch-01.png", "assets/gluvia/watch-02.png", "assets/gluvia/watch-03.png", "assets/gluvia/watch-04.png"][i]}));
const frameOrder=[34,23,24,25,26,27,28,29,30,31,35,37,36,32];
const frameStart=hqGluvia.length;
frameOrder.forEach((n,i)=>{const c=gluviaOriginalChapters[i];c.src=["assets/gluvia/frame-34.png", "assets/gluvia/frame-23.png", "assets/gluvia/frame-24.png", "assets/gluvia/frame-25.png", "assets/gluvia/frame-26.png", "assets/gluvia/frame-27.png", "assets/gluvia/frame-28.png", "assets/gluvia/frame-29.png", "assets/gluvia/frame-30.png", "assets/gluvia/frame-31.png", "assets/gluvia/frame-35.png", "assets/gluvia/frame-37.png", "assets/gluvia/frame-36.png", "assets/gluvia/frame-32.png"][i];c.asset=frameStart+i;hqGluvia.push({title:c.title+' — original presentation',src:c.src})});
function deviceCollection(start,end){return `<div class="hq-grid">${hqGluvia.slice(start,end).map((a,i)=>`<button data-hq="${start+i}"><img src="${a.src}" alt="${esc(a.title)} — original Figma export" loading="lazy" decoding="async"><span>${esc(a.title)} ↗</span></button>`).join('')}</div>`}
function curatedMockup(i,caption){const a=hqGluvia[i];return `<figure><button data-hq="${i}" aria-label="Enlarge ${esc(a.title)}"><img src="${a.src}" alt="${esc(a.title)} — Kritika’s original design" loading="lazy" decoding="async"></button><figcaption>${caption}<span>Tap to inspect ↗</span></figcaption></figure>`}

const researchNotes=[['Improve medication adherence','Medication records give daily treatment routines a place in the mobile experience.'],['Reduce daily management hassles','The overview, meals, and logbook gather everyday tasks into a shared interface.'],['Enable proactive interventions','The wider concept explores patterns, insights, and a care-team perspective.'],['Strengthen care collaboration','Care Circle makes caregivers and care relationships visible.'],['Make healthy choices easier','Meals, activity, and daily context sit alongside glucose information.']];
function originalBoard(asset,caption,note=''){const a=hqGluvia[asset];return `<figure class="curated-problem"><button data-hq="${asset}" aria-label="Enlarge ${esc(a.title)}"><img src="${a.src}" alt="${esc(a.title)} — original GLUVIA board" loading="lazy"></button><figcaption><span class="problem-caption-title">${caption}</span>${note?`<span class="problem-provenance">${note}</span>`:''}<button class="problem-enlarge" data-hq="${asset}">Explore the frame ↗</button></figcaption></figure>`}
function researchExperience(){return `<section class="research-experience"><span class="eyebrow">THE REAL PAIN / DECISION FATIGUE</span><h3>A day filled with<br>small decisions.</h3><p>The original journey follows six moments: waking up, work, lunch, the afternoon, dinner, and bedtime. It frames the mental load behind everyday management, from understanding a reading to thinking about food, movement, and rest.</p></section>${originalBoard(26,'The everyday journey — from waking up to going to sleep.','The quotation in this original concept board has not been verified as interview evidence.')}<section class="research-experience"><span class="eyebrow">RESEARCH BOARD / SYSTEM MAPPING</span><h3>Look beyond the app.</h3><p>The research board maps a person with diabetes within a wider network: caregivers, healthcare providers, hospitals, pharmacies, and devices such as glucometers and smart wearables.</p><div class="research-stakeholders" aria-label="Stakeholders in the original board">${['Users','Caregivers','Doctors','Pharma','Policy makers'].map(t=>`<span>${t}</span>`).join('')}</div><p class="research-cycle">Monitor <span>→</span> Understand <span>→</span> Decide <span>→</span> Act <span>→</span> Improve</p><p>The board’s ambition is to extend the experience beyond a single app and consider everyone involved. Its five sticky notes capture the intended opportunities.</p><div class="research-notes">${researchNotes.map((n,i)=>`<button data-research-note="${i}" aria-pressed="${i===0}" aria-controls="research-note-detail"><span>0${i+1}</span>${n[0]}<small>Explore idea ↗</small></button>`).join('')}</div><div id="research-note-detail" class="research-note-detail" aria-live="polite"><h4>${researchNotes[0][0]}</h4><p>${researchNotes[0][1]}</p></div><p class="research-caption">Concept opportunities from the original board, with connections to the interface design.</p></section>${originalBoard(25,'The original research board: stakeholders, decision cycle, and opportunity notes.')}`}
const galleryGroups=[{name:'Overview & insights',ids:[0,1,2,8,9,13],desc:'Glucose information, trends, and connected devices.'},{name:'Everyday records',ids:[4,5,10,15,16],desc:'Meals, medication, and the logbook, including the original light and dark treatments.'},{name:'People & guidance',ids:[3,7,11,17],desc:'Profile, Care Circle, and the AI-coach concept, including its alternate design.'},{name:'Getting started',ids:[6,12,14],desc:'The original registration and sign-up explorations.'},{name:'On the wrist',ids:[18,19,20,21,22],desc:'Glucose, activity, sleep, insulin, and insight views for the watch.'}];
const mockupCaptions=['Glucose monitor composition with its original device presentation.','The daily overview brings the reading and daily totals together.','Connected watch information within the mobile experience.','The original AI-coach conversation concept.','Meal details combine the food image, nutritional information, and logging action.','A timeline for revisiting glucose, meal, and medication entries.','An original sign-up exploration for account creation.','Profile information and personal settings.','A dedicated view for patterns and daily insights.','Glucose history and statistics in a focused view.','A meal-entry form with description, photo, and meal timing.','An alternate exploration of the AI-coach interface.','The registration form and its account fields.','A view of devices within the connected experience.','An alternate sign-up treatment from the original collection.','Medication records in the original dark treatment.','Medication records in the original light treatment.','People, roles, and updates within Care Circle.','A compact glucose reading and trend on the watch.','Activity and movement information on the wrist.','The watch sleep summary.','The original insulin information view.','A compact insight concept for the watch.'];
function galleryContent(n){const g=galleryGroups[n];return `<section class="mockup-chapter" id="mockup-group-${n}" aria-labelledby="mockup-heading-${n}"><div class="mockup-chapter-heading"><span class="eyebrow">${n===4?'WATCH COLLECTION':'MOBILE COLLECTION'} / ${g.ids.length} ORIGINAL VIEWS</span><h4 id="mockup-heading-${n}">${g.name}</h4><p>${g.desc}</p></div><div class="complete-mockup-grid ${n===4?'watch-collection-grid':''}">${g.ids.map(i=>curatedMockup(i,`<b>${hqGluvia[i].title}</b>${mockupCaptions[i]}`)).join('')}</div></section>`}
function completeGallery(){return `<section class="complete-gallery"><span class="eyebrow">THE INTERFACE COLLECTION / 23 ORIGINAL VIEWS</span><h3>Everyday details.<br>A shared design language.</h3><p>All 18 mobile exports and five watch views are shown below, grouped by purpose. Select a section to jump to it, or keep scrolling. Every mockup opens at its original resolution.</p><div class="gallery-filter" role="group" aria-label="Browse original mockups">${galleryGroups.map((g,i)=>`<button data-gallery-group="${i}" aria-controls="mockup-group-${i}">${g.name}<span>${g.ids.length}</span></button>`).join('')}</div><div id="gallery-content">${[4,3,0,1,2].map(galleryContent).join('')}</div></section>`}
function slowLook(){return `<section class="original-scroll-demo"><div><span class="eyebrow">A CLOSER LOOK / ORIGINAL MOBILE ARTWORK</span><h3>Take a slower look.</h3><p>Scroll through the original daily overview, or play a gentle pan to explore its details.</p><button data-scroll-play aria-pressed="false">Play scroll preview</button><button data-scroll-reset>Back to top</button><p class="research-caption">Presentation of the original design; screen controls are not interactive.</p></div><div class="original-scroll-window" tabindex="0" aria-label="Scroll original daily overview"><img src="${hqGluvia[1].src}" alt="Original daily overview phone mockup" loading="lazy"></div></section>`}
const guidedSteps=[{label:'Orient',title:'Start with the daily picture.',body:'The overview brings the current reading, recent context, and daily totals into one starting point.',question:'What information is available now?',asset:1},{label:'Record',title:'Give a meal its own context.',body:'A dedicated meal form brings the description, carbohydrate entry, photograph, and meal time into one task.',question:'What happened around this moment?',asset:10},{label:'Revisit',title:'Return to the record.',body:'The logbook groups daily entries in a timeline, making individual moments available for later review.',question:'What was recorded through the day?',asset:5},{label:'Reflect',title:'Step back to see the history.',body:'The statistics view brings historical glucose information into focus, completing the move from an individual moment to a broader picture.',question:'How does this moment sit within the history?',asset:9}];
function guidedPanel(i){const g=guidedSteps[i];return `<div class="guided-copy"><span class="eyebrow">0${i+1} / 04 · ${g.label.toUpperCase()}</span><h3>${g.title}</h3><p>${g.body}</p><blockquote>${g.question}</blockquote><div class="guided-controls"><button data-journey-step="${i-1}" ${i===0?'disabled':''}>← Previous</button><button data-journey-step="${i===3?0:i+1}">${i===3?'Start again ↺':'Next moment →'}</button></div></div><div class="guided-device">${curatedMockup(g.asset,hqGluvia[g.asset].title)}</div>`}
function guidedJourney(){return `<section class="guided-journey"><span class="eyebrow">FOLLOW THE EXPERIENCE</span><h3>From a moment<br>to a daily picture.</h3><p class="guided-intro">Explore four connected moments in GLUVIA’s mobile concept.</p><div class="guided-tabs" role="group" aria-label="Choose journey moment">${guidedSteps.map((g,i)=>`<button data-journey-step="${i}" aria-pressed="${i===0}" aria-controls="guided-panel">0${i+1} ${g.label}</button>`).join('')}</div><div id="guided-panel" class="guided-panel" data-current-step="0">${guidedPanel(0)}</div><p class="guided-footnote">A guided presentation of the original screens. Entries and readings are illustrative; no data is submitted.</p></section>`}
const contextInsights=[{title:'Care has an emotional dimension.',finding:'CDC describes diabetes distress as the worry, frustration, and exhaustion that can accompany daily diabetes care.',connection:'GLUVIA’s daily-journey framing makes room for the person’s experience alongside the numbers.',labels:['Reading','Daily routine','Emotional context'],source:'Diabetes and Mental Health',url:'https://www.cdc.gov/diabetes/living-with/mental-health.html'},{title:'Management spans several activities.',finding:'CDC’s self-management education overview includes eating, activity, medication, monitoring, coping, and problem solving.',connection:'The overview, meal records, medication screens, and logbook give these everyday activities distinct places within the concept.',labels:['Meals','Medication','Daily record'],source:'Diabetes Self-Management Education and Support',url:'https://www.cdc.gov/diabetes/education-support-programs/index.html'},{title:'Support is personal.',finding:'CDC discusses involving family, friends, and care teams, including explaining how and when their help is useful.',connection:'Care Circle represents those relationships in the interface. It is a design response to this context, not evidence of improved care.',labels:['Individual','Loved ones','Care team'],source:'10 Tips for Coping with Diabetes Distress',url:'https://www.cdc.gov/diabetes/articles/10-tips-coping-diabetes-distress.html'}];
function contextPanel(i){const c=contextInsights[i];return `<div class="context-visual" aria-hidden="true"><span class="context-center">${i===0?'A whole person':i===1?'A connected day':'A care circle'}</span>${c.labels.map((l,n)=>`<span class="context-node node-${n}">${l}</span>`).join('')}<span class="context-orbit"></span></div><div class="context-copy"><span class="eyebrow">0${i+1} / PUBLISHED CONTEXT</span><h4>${c.title}</h4><p>${c.finding}</p><a href="${c.url}" target="_blank" rel="noopener">CDC · ${c.source} ↗</a><div class="context-connection"><b>Connection to GLUVIA</b><p>${c.connection}</p></div></div>`}
function sourcedContext(){return `<section class="sourced-context"><span class="eyebrow">SECONDARY RESEARCH / CONTEXT FOR THE CONCEPT</span><h3>There’s a person<br>behind every reading.</h3><p>Published diabetes resources provide context for three themes in GLUVIA. Choose a theme to explore the connection.</p><div class="context-tabs" role="group" aria-label="Research themes">${['Mental load','Everyday management','Personal support'].map((t,i)=>`<button data-context="${i}" aria-pressed="${i===0}" aria-controls="context-panel">${t}</button>`).join('')}</div><div id="context-panel" class="context-panel">${contextPanel(0)}</div><p class="context-method">Sources reviewed for this portfolio. The design connections are interpretations, not participant findings or measured product outcomes.</p></section>`}
function hardwareExploration(){return `<section class="hardware-exploration"><span class="eyebrow">BEYOND THE SCREEN / SPECULATIVE HARDWARE</span><h3>The microchip.<br>A wider design question.</h3><p>The original project explores whether sensing, information, and insulin delivery could become a more integrated wearable experience. The microchip board makes that ambition tangible through an exploded component view and a proposed interaction sequence.</p><div class="hardware-scope"><span>Mobile experience</span><i aria-hidden="true">→</i><span>Wearable interface</span><i aria-hidden="true">→</i><span>Hardware concept</span></div><p class="hardware-status">This is a speculative design exploration, not an engineered or clinically validated device. Claims of precision, autonomous dosing, and clinical validation within the original artwork are not established results.</p></section>${originalBoard(31,'Original microchip exploration — the wider ecosystem vision.','Concept artwork; feasibility and medical performance are unverified.')}`}
function caseFinale(){return `<footer class="case-finale"><div class="finale-heading"><span class="eyebrow">GLUVIA / A CONCEPT BY KRITIKA</span><h3>Designed around life.<br><em>Beyond the numbers.</em></h3><p>One connected vision. A person at the centre.</p></div><div class="finale-stage" aria-label="Original GLUVIA screens"><div class="finale-halo" aria-hidden="true"></div>${[10,1,17].map((i,n)=>`<button class="finale-screen finale-screen-${n}" data-hq="${i}" aria-label="Inspect ${hqGluvia[i].title} in closing showcase"><img src="${hqGluvia[i].src}" alt="${hqGluvia[i].title} — original GLUVIA mockup" loading="lazy"></button>`).join('')}</div><div class="finale-bottom"><span>Thoughtful systems. Human details.</span><div><button data-finale-replay>Replay reveal ↺</button><button data-case-top>Back to the story ↑</button><button data-case-close>More work ↗</button></div></div></footer>`}
gluviaSourceView=()=>`<article class="curated-case"><header class="curated-header"><span class="eyebrow">KRITIKA / PERSONAL CONCEPT / PRODUCT + STRATEGY</span><h2>GLUVIA<span>Care, beyond<br>the numbers.</span></h2><p class="curated-deck">A diabetes management ecosystem connecting everyday information, wearable moments, and the people around you.</p><div class="curated-meta"><span><b>The challenge</b>Make daily information easier to connect.</span><span><b>The direction</b>Mobile depth. Watch simplicity. Shared care.</span><span><b>The stage</b>Personal design concept</span></div></header><img class="case-hero" src="assets/gluvia/frame-34.png" alt="GLUVIA diabetes management concept with Kritika’s original phone and watch mockups"><section class="curated-intro"><span class="eyebrow">01 / THE OPPORTUNITY</span><h3>Design around a day.<br>Not just a data point.</h3><div><p>GLUVIA frames diabetes management around the decisions woven through a day: meals, medication, movement, and rest. The concept brings glucose information, daily records, and shared care into one connected experience.</p><p>The central design question: how can information become easier to connect to everyday life? This shifts the focus from an isolated reading to the context and people around it.</p></div></section><figure class="curated-problem"><button class="source-image-button" data-hq="24" aria-label="Enlarge original GLUVIA problem frame"><img src="assets/gluvia/frame-23.png" alt="Kritika’s original problem frame: diabetes management as a daily decision-making challenge" loading="lazy" decoding="async"></button><figcaption><span class="problem-caption-title">The problem, as framed in the original concept.</span><span class="problem-provenance">Statistics shown in this original board are unverified.</span><button class="problem-enlarge" data-hq="24">Explore the frame ↗</button></figcaption></figure>${researchExperience()}${sourcedContext()}${guidedJourney()}<section class="curated-decision"><div class="curated-copy"><span class="eyebrow">02 / UNDERSTAND</span><h3>Start with now.<br>Make room for patterns.</h3><p>The home screen puts the current glucose reading first, with daily context around it. A dedicated statistics view makes space for history and patterns.</p><div class="curated-note"><b>Two levels of detail</b><p>A quick overview for the present moment; a deeper view for reviewing change over time.</p></div></div><div class="curated-pair">${curatedMockup(1,'A clear starting point for the day.')}${curatedMockup(9,'A separate space to explore trends.')}</div></section>${slowLook()}<section class="curated-decision alternate"><div class="curated-copy"><span class="eyebrow">03 / ADD CONTEXT</span><h3>Give the numbers<br>a little more meaning.</h3><p>Meal entry and the logbook give daily events a place beside glucose information. The form captures an individual meal; the logbook brings entries together in a record that can be revisited.</p><div class="curated-note"><b>From an entry to a daily picture</b><p>A focused form for recording a moment, paired with a timeline for looking back across the day.</p></div></div><div class="curated-pair">${curatedMockup(10,'Capture a meal in a dedicated flow.')}${curatedMockup(5,'Return to a record of the day.')}</div></section><section class="curated-decision"><div class="curated-copy"><span class="eyebrow">04 / CONNECT</span><h3>A glance on the wrist.<br>A circle of support.</h3><p>The watch presents compact glucose information for a quick glance. On the phone, Care Circle brings people and their roles into view, making shared care a visible part of the experience.</p><div class="curated-note"><b>Different touchpoints, distinct roles</b><p>The phone holds the detail. The watch keeps key information close. Care Circle connects the experience to the people around it.</p></div></div><div class="curated-pair">${curatedMockup(18,'Quick glucose information on the watch.')}${curatedMockup(17,'People and roles in the care circle.')}</div></section><section class="curated-scope"><span class="eyebrow">05 / THE ECOSYSTEM</span><h3>Individual moments.<br>A connected picture.</h3><p>GLUVIA’s visual system extends across everyday self-management, wearable interactions, and a broader care-team concept. Each touchpoint contributes a different perspective on the same day.</p><div class="scope-columns"><div><span class="scope-tag">EVERYDAY EXPERIENCE</span><h4>Understand · Record · Connect</h4><p>Glucose history, meal and medication records, and Care Circle form the core mobile experience. The watch brings selected information into a compact format.</p></div><div><span class="scope-tag muted">CONCEPT EXPLORATIONS</span><h4>Coaching · Hardware · Care teams</h4><p>The wider project explores an AI coach, insulin-delivery hardware, and a clinician dashboard as possible extensions of the ecosystem.</p></div></div></section>${hardwareExploration()}<section class="curated-reflection"><span class="eyebrow">06 / DESIGN LANGUAGE</span><h3>Human in tone.<br>Connected in detail.</h3><p>Purple accents connect the mobile and watch interfaces. Rounded surfaces, prominent readings, and light and dark treatments give the system a shared visual language while allowing each screen to serve a different task.</p><div class="curated-principles"><div><b>Empathise</b><p>Everyday life sets the context.</p></div><div><b>Simplify</b><p>Give each screen a clear purpose.</p></div><div><b>Connect</b><p>Bring touchpoints and people together.</p></div><div><b>Empower</b><p>Keep the person at the centre.</p></div></div><p>These principles from the original project connect an individual reading, a daily record, and a care circle through one design direction.</p><p class="curated-evidence">GLUVIA — a personal product and strategic design concept by Kritika.</p></section>${completeGallery()}${caseFinale()}</article>`;
