document.querySelector('#projectDetail').addEventListener('click',e=>{const note=e.target.closest('[data-research-note]');if(note){const n=researchNotes[Number(note.dataset.researchNote)];document.querySelectorAll('[data-research-note]').forEach(b=>b.setAttribute('aria-pressed',String(b===note)));document.querySelector('#research-note-detail').innerHTML=`<h4>${n[0]}</h4><p>${n[1]}</p>`}const group=e.target.closest('[data-gallery-group]');if(group){const d=document.querySelector('#projectDialog'),target=document.querySelector('#mockup-group-'+group.dataset.galleryGroup);d.scrollTo({top:d.scrollTop+target.getBoundingClientRect().top-d.getBoundingClientRect().top-20,behavior:'instant'})}if(e.target.closest('[data-scroll-reset]')){stopOriginalScroll();document.querySelector('.original-scroll-window').scrollTop=0}if(e.target.closest('[data-scroll-play]')){if(originalScrollFrame){stopOriginalScroll();return}const w=document.querySelector('.original-scroll-window'),b=document.querySelector('[data-scroll-play]');if(reducedMotion.matches){w.scrollTop=w.scrollHeight-w.clientHeight;return}if(w.scrollTop>=w.scrollHeight-w.clientHeight-2)w.scrollTop=0;let last=0,position=w.scrollTop;b.textContent='Pause scroll preview';b.setAttribute('aria-pressed','true');const tick=t=>{if(!document.querySelector('#projectDialog').open||document.hidden||reducedMotion.matches||data.motionPaused){stopOriginalScroll();return}if(last)position+=Math.min(t-last,50)*.024;last=t;w.scrollTop=Math.round(position);if(w.scrollTop>=w.scrollHeight-w.clientHeight-1){stopOriginalScroll();return}originalScrollFrame=requestAnimationFrame(tick)};originalScrollFrame=requestAnimationFrame(tick)}});
