const auraStart=hqGluvia.length;const auraAssets=[{"src": "assets/aura/board-00.png", "title": "AURA cover"}, {"src": "assets/aura/board-01.png", "title": "Opening scenario"}, {"src": "assets/aura/board-02.png", "title": "Design challenge"}, {"src": "assets/aura/board-03.png", "title": "Persona explorations"}, {"src": "assets/aura/board-04.png", "title": "Primary research statement"}, {"src": "assets/aura/board-05.png", "title": "Would you rather \u2014 home and interface"}, {"src": "assets/aura/board-06.png", "title": "Demographic trends"}, {"src": "assets/aura/board-07.png", "title": "Journey \u2014 independence and change"}, {"src": "assets/aura/board-08.png", "title": "Journey \u2014 response and autonomy"}, {"src": "assets/aura/board-09.png", "title": "Mobile interfaces"}, {"src": "assets/aura/board-10.png", "title": "Technology perception"}, {"src": "assets/aura/board-11.png", "title": "Product concept"}, {"src": "assets/aura/board-12.png", "title": "Ideation sketches"}, {"src": "assets/aura/board-13.png", "title": "Spatial rendering"}, {"src": "assets/aura/board-14.png", "title": "Home environments"}, {"src": "assets/aura/board-15.png", "title": "Design intent"}, {"src": "assets/aura/board-16.png", "title": "Behavioural insights"}, {"src": "assets/aura/board-17.png", "title": "Would you rather \u2014 communication"}, {"src": "assets/aura/board-18.png", "title": "Opportunity clustering"}, {"src": "assets/aura/board-19.png", "title": "Colour, material and finish"}];hqGluvia.push(...auraAssets,{src:"assets/aura/editorial-home.png",title:"AURA illustrative editorial image"});

const auraProject={id:'aura',title:'AURA',subtitle:'A voice-assisted home companion for confidence and connection.',category:'Strategy',year:'Concept project',theme:'common',image:'',role:'Strategic design · Service concept · Interface exploration',challenge:'How might the home support independence without making everyday life feel monitored?',approach:'A concept connecting domestic environments, resident choice, and a wider circle of care.',outcome:'A spatial and digital service concept, with original interface, journey, and material explorations.',concept:true};
defaults.projects.splice(1,0,structuredClone(auraProject));if(!data.projects.some(p=>p.id==='aura')){data.projects.splice(1,0,structuredClone(auraProject));try{localStorage.setItem(key,JSON.stringify(data))}catch{}}
const auraNotes=[['Independence is the starting point.','Autonomy and the fear of being a burden sit alongside physical safety.','Strategic implication','Give the resident meaningful choices about prompts and sharing.'],['The home is part of the service.','Lighting, flooring, materials, and interfaces shape one experience.','Strategic implication','Treat installation, maintenance, and everyday controls as part of the experience.'],['Support has more than one audience.','The concept connects a resident with family members living elsewhere and a wider care network.','Strategic implication','Separate reassurance for family from control over the resident.'],['Quiet should not mean opaque.','Support should blend into a familiar domestic environment.','Strategic implication','Make system activity, permissions, and manual overrides understandable.']];
function auraBoard(i,caption){return `<figure class="aura-board"><button data-hq="${auraStart+i}" aria-label="Enlarge AURA ${auraAssets[i].title}"><img src="${auraAssets[i].src}" alt="${auraAssets[i].title} — Kritika’s original AURA board" loading="lazy"></button><figcaption>${caption||auraAssets[i].title}<span>View board ↗</span></figcaption></figure>`}
function auraNotePanel(i){const n=auraNotes[i];return `<span class="aura-kicker">${n[2]}</span><h4>${n[0]}</h4><p>${n[1]}</p><strong>${n[3]}</strong>`}
const auraMoments=[['02:13','A little more light?','In the original scenario, Maria gets up during the night. The concept offers a gentle lighting adjustment.','Ask the resident before changing the experience.'],['02:14','The choice stays with Maria.','A simple “Yes please” or “Not right now” response keeps the interaction brief.','A proposal for assistance, not automatic consent.'],['02:15','Reassurance, within boundaries.','A family update is part of the proposed service when the resident has chosen to share it.','The service concept depends on explicit permissions and a defined support arrangement.']];
function auraMoment(i){const m=auraMoments[i];return `<span class="aura-time">${m[0]}</span><h4>${m[1]}</h4><p>${m[2]}</p><small>${m[3]}</small>`}
function auraView(){return `<article class="aura-case"><header class="aura-arrival"><div class="aura-arrival-top"><span class="aura-arrival-wordmark">aura<span>✳</span></span><span>KRITIKA / STRATEGIC DESIGN</span><span class="aura-concept-pill"><i></i> Concept exploration</span></div><div class="aura-arrival-grid"><div class="aura-arrival-copy"><span class="aura-kicker">SMART LIVING FOR LATER LIFE</span><h2>More life.<br><em>Less intrusion.</em></h2><p>A voice-assisted home companion for night-time confidence and connection. Discreet support, in the home you love.</p><div class="aura-arrival-actions"><button data-aura-jump=".aura-framing">Explore the story <span>↘</span></button><button data-aura-jump=".aura-screen-section">Experience AURA ↗</button></div><div class="aura-arrival-principle"><span>THE IDEA AT HEART</span><p>Support that belongs in your life.<br>And feels like it belongs at home.</p></div></div><figure class="aura-arrival-image"><img src="assets/aura/editorial-home.png" alt="Illustrative older woman tending plants in a sunlit home"><div class="aura-arrival-orbit" aria-hidden="true"></div><div class="aura-arrival-glass"><span class="aura-arrival-symbol" aria-hidden="true">⌂</span><div><small>DESIGNED AROUND YOU</small><strong>Your home.<br>Your rhythm.</strong></div><span class="aura-arrival-spark" aria-hidden="true">✳</span></div><figcaption>AI-generated illustration</figcaption></figure></div><div class="aura-arrival-bottom"><div><small>01 / CONTEXT</small><span>Ageing in place</span></div><div><small>02 / DESIGN LENS</small><span>People + place + care</span></div><div><small>03 / EXPLORATION</small><span>Strategy → service → interface</span></div><button data-aura-jump=".aura-framing" aria-label="Scroll to AURA story">↓</button></div></header><section class="aura-section aura-framing"><span class="aura-kicker">01 / THE STARTING QUESTION</span><h3>How can support feel<br>like part of home?</h3><div class="aura-two"><p>I began with Europe’s ageing population and a question: how could the home support independence while keeping people connected to those they trust?</p><p>AURA shifts the design focus from a single assistive object to the relationship between a person, their surroundings, and the people they trust. The intended value is everyday agency, with support available in the background.</p></div></section><section class="aura-section aura-research"><span class="aura-kicker">02 / PUBLISHED CONTEXT</span><h3>A changing population.<br>A broader design responsibility.</h3><div class="aura-evidence-grid"><article class="aura-glass"><b class="aura-stat">22%</b><h4>of the EU population was aged 65+ in 2025.</h4><p>Eurostat reports an increase from 17% in 2005. This establishes the scale of the context, not demand for a particular product.</p><a href="https://ec.europa.eu/eurostat/web/interactive-publications/demography-2026" target="_blank" rel="noopener">Eurostat · Demography 2026 ↗</a></article><article class="aura-glass"><span class="aura-stat">Ability</span><h4>Life is the outcome.</h4><p>WHO frames healthy ageing around what people can be and do, and the relationship between personal capacity and environment.</p><a href="https://www.who.int/news-room/questions-and-answers/item/healthy-ageing-and-functional-ability" target="_blank" rel="noopener">WHO · Healthy ageing ↗</a></article><article class="aura-glass"><span class="aura-stat">Choice</span><h4>No single older-person experience.</h4><p>WHO’s age-friendly approach recognises varied capacities and circumstances, and respects people’s decisions and preferences.</p><a href="https://www.who.int/teams/social-determinants-of-health/demographic-change-and-healthy-ageing/age-friendly-environments" target="_blank" rel="noopener">WHO · Age-friendly environments ↗</a></article></div></section><section class="aura-section"><span class="aura-kicker">03 / FROM CONTEXT TO DIRECTION</span><h3>Four ideas that<br>hold the system together.</h3><div class="aura-sticky-grid">${auraNotes.map((n,i)=>`<button data-aura-note="${i}" aria-pressed="${i===0}" aria-controls="aura-note-panel"><small>0${i+1} / STRATEGIC THEME</small>${n[0]}<span>Explore ↗</span></button>`).join('')}</div><div class="aura-glass aura-note-panel" id="aura-note-panel" aria-live="polite">${auraNotePanel(0)}</div></section>${auraEvidenceBridge()}<section class="aura-section aura-working-charts"><details><summary>Original exploratory charts <span>8 charts from the concept development</span></summary>${auraResearchCharts()}</details></section>${auraPeople()}${auraBoard(18,'Mapping emotional, practical, and technological opportunities.')}<section class="aura-section aura-choices"><span class="aura-kicker">04 / EXPLORING TRADEOFFS</span><h3>Different preferences.<br>Different kinds of support.</h3><p>I used a “Would you rather?” game with approximately 9–10 older adults to discuss home, technology, and everyday support. Their responses highlighted a desire to stay in familiar surroundings, unease at night, concerns about kitchen accidents, and loneliness. Explore the prompts below.</p><div class="aura-choice-grid">${[['Stay in your home or move to a fully assisted smart home?','My Home','Smart home'],['Interact with a simple voice assistant for all tasks, or use a more complex tablet app with more features?','Simple voice assistant','Tablet app'],['System that talks you daily or only for updates?','Daily talks','Only updates']].map((q,i)=>`<fieldset class="aura-glass"><legend>${q[0]}</legend><div>${q.slice(1).map((v,j)=>`<label><input type="radio" name="aura-choice-${i}" value="${j}"><span>${v}</span></label>`).join('')}</div></fieldset>`).join('')}</div><p class="aura-choice-response" aria-live="polite">Choose what feels right to you.</p><aside class="aura-game-insight"><span class="aura-kicker">KEY RESEARCH TAKEAWAY</span><h4>Supporting ageing means supporting autonomy.</h4><p>Most participants wanted to remain at home without very visible changes. This supported a direction of seamless home integration: familiar spaces, subtle assistance, and control that stays with the resident.</p><div><span>Unobtrusive support</span><span>Autonomy first</span><span>Home as part of care</span></div></aside></section>${auraParticipantInsights()}<section class="aura-section aura-scenario"><div><span class="aura-kicker">05 / A MOMENT IN THE SERVICE</span><h3>It’s 2:13 AM.<br>Home responds quietly.</h3><p>A night-time scenario exploring how support can stay gentle and optional.</p><div class="aura-moment-tabs" role="group" aria-label="AURA scenario moments">${['Notice','Offer','Connect'].map((t,i)=>`<button data-aura-moment="${i}" aria-pressed="${i===0}" aria-controls="aura-moment">0${i+1} ${t}</button>`).join('')}</div></div><div class="aura-glass aura-moment" id="aura-moment" aria-live="polite">${auraMoment(0)}</div></section>${auraProductConcept()}${auraScreens()}<section class="aura-section"><span class="aura-kicker">06 / THE SERVICE BEHIND THE SCREEN</span><h3>A home experience<br>needs a support system.</h3><p>This proposed service model connects the original spatial and interface ideas to the people and operations that would sustain them.</p>${auraEcosystem()}<div class="aura-service"><article><span>RESIDENT</span><h4>Control the experience.</h4><p>Choose prompts, adjust the environment, and decide what to share.</p></article><article><span>TRUSTED CIRCLE</span><h4>Receive agreed updates.</h4><p>Family and care contacts have distinct roles; connection should not imply unrestricted access.</p></article><article><span>SERVICE PROVIDER</span><h4>Keep the system dependable.</h4><p>Installation, maintenance, consent setup, and support belong in the service scope.</p></article></div><details class="aura-detail"><summary>The strategic tradeoff: ambient support and personal control</summary><p>Environmental sensing may reduce reliance on a wearable, but introduces installation cost and privacy questions. A proposed first scope is resident-controlled lighting and understandable updates. Predictive health claims require separate technical and clinical evidence.</p></details></section>${auraBoard(12,'Ideation: embedded panels, companion forms, materials, and a walking aid.')}${auraBoard(13,'Spatial concept: integrated flooring and adaptive lighting. Prediction remains an untested capability.')}${auraBoard(19,'Colour, material, and finish: warmth, domestic familiarity, and soft surfaces.')}<section class="aura-section aura-outcome"><span class="aura-kicker">07 / DESIGN OUTCOME</span><h3>A home that supports<br><em>the life already there.</em></h3><p>AURA connects the home, everyday controls, and a trusted support network in one concept for ageing in place. The aim is to make assistance accessible while preserving the resident’s choices.</p><div class="aura-glass aura-outcome-row"><span>Spatial intelligence</span><span>Resident choice</span><span>Connected support</span></div></section><footer class="aura-footer"><span class="aura-kicker">AURA / BY KRITIKA</span><h3>Technology in the background.<br><em>Life in the foreground.</em></h3><div><button data-case-top>Back to the story ↑</button><button data-case-close>Explore more work ↗</button></div></footer></article>`}
document.querySelector('#projectDetail').addEventListener('click',e=>{const n=e.target.closest('[data-aura-note]');if(n){document.querySelectorAll('[data-aura-note]').forEach(b=>b.setAttribute('aria-pressed',String(b===n)));document.querySelector('#aura-note-panel').innerHTML=auraNotePanel(Number(n.dataset.auraNote))}const m=e.target.closest('[data-aura-moment]');if(m){document.querySelectorAll('[data-aura-moment]').forEach(b=>b.setAttribute('aria-pressed',String(b===m)));document.querySelector('#aura-moment').innerHTML=auraMoment(Number(m.dataset.auraMoment))}});
