function auraPeople(){return `<section class="aura-section aura-people"><span class="aura-kicker">RESEARCH LENS / PERSONA MAPPING</span><h3>Two perspectives.<br>One shared sense of home.</h3><p>Two concept personas shaped the experience: Maria wants to stay independent; Elena wants to stay connected without taking over.</p><div class="aura-persona-grid"><article class="aura-glass"><div class="aura-persona-heading"><span class="aura-avatar">M</span><div><small>THE RESIDENT</small><h4>Maria, 74</h4><span>Retired teacher · lives alone</span></div></div><dl><dt>Wants to preserve</dt><dd>Independence, familiar routines, and social connection.</dd><dt>Friction</dt><dd>Complex technology, fear of an emergency, and unwanted monitoring.</dd><dt>Experience priority</dt><dd>A simple way to accept, decline, or adjust support.</dd></dl><div class="aura-persona-decision">DESIGN RESPONSE ↗<p>Plain-language prompts and a visible “Not right now” choice.</p></div></article><article class="aura-glass"><div class="aura-persona-heading"><span class="aura-avatar">E</span><div><small>THE DAUGHTER</small><h4>Elena, 42</h4><span>Working full-time · supports from afar</span></div></div><dl><dt>Wants to preserve</dt><dd>Connection with her mother alongside work and family life.</dd><dt>Friction</dt><dd>Uncertainty between updates and limited communication with care providers.</dd><dt>Experience priority</dt><dd>Understand what has been shared, when it was updated, and what needs a response.</dd></dl><div class="aura-persona-decision">DESIGN RESPONSE ↗<p>A permission-based overview with clear update times.</p></div></article></div><div class="aura-shared"><span>MARIA’S AGENCY</span><b>Reassurance with permission</b><span>ELENA’S CONNECTION</span></div><button class="aura-source-button" data-hq="${auraStart+3}">Persona mapping ↗</button></section><section class="aura-section aura-behaviour"><span class="aura-kicker">BEHAVIOURAL INSIGHTS / DESIGN IMPLICATIONS</span><h3>Support is personal.<br>Control should be, too.</h3><p>Three behavioural themes shaped the design direction: independence, confidence, and control.</p><div class="aura-insight-list">${[['01','Independence has emotional value.','Living independently is linked to identity, not only the ability to complete tasks.','Keep familiar routines central. Make assistance optional and adjustable.'],['02','Small moments deserve attention.','Minor falls and near-falls bring everyday confidence into focus.','Explore a clear, low-effort lighting interaction for moving around at night.'],['03','Safety can feel like loss of control.','Protection can create tension when it reduces personal control.','Let residents decide which updates reach their trusted circle.']].map(n=>`<details class="aura-insight" open><summary><span>${n[0]}</span>${n[1]}</summary><div><p>${n[2]}</p><p><small>DESIGN IMPLICATION</small>${n[3]}</p></div></details>`).join('')}</div><button class="aura-source-button" data-hq="${auraStart+16}">Behavioural research ↗</button></section>`}
function auraScreens(){return `<section class="aura-section aura-screen-section"><span class="aura-kicker">INTERFACE DESIGN / EVERYDAY MOMENTS</span><h3>Less to navigate.<br>More to understand.</h3><p>One calm visual language, adapted to three moments: everyday control, a brief night-time choice, and reassurance at a distance.</p><p class="aura-small">Interactive prototype · sample data</p><div class="aura-phone-grid"><article class="aura-screen-column"><div class="aura-phone"><div class="aura-phone-status"><span>09:41</span><span>••• ▰</span></div><div class="aura-phone-body"><div class="aura-app-brand">aura <span>MY HOME</span></div><h4>Good morning,<br>Maria.</h4><p class="aura-phone-muted">A little support for your day.</p><div class="aura-home-orb"><span>⌂</span></div><div class="aura-ui-card"><small>HOME CONNECTION</small><h5>Connected</h5><p>Updated 2 minutes ago</p></div><div class="aura-ui-row"><h5>Your day</h5><span>Today</span></div><div class="aura-timeline"><span>10:00</span><p>Time in the garden<small>Your personal reminder</small></p></div><div class="aura-timeline"><span>16:30</span><p>Call Elena<small>Your personal reminder</small></p></div><div class="aura-voice-control"><small>VOICE CONTROL · SIMULATED</small><button class="aura-app-secondary" data-aura-voice="start" aria-pressed="false">Try voice control</button><p class="aura-voice-status" aria-live="polite">Microphone off</p><div class="aura-voice-commands" hidden><button data-aura-voice="lamp">“Turn on the hallway light”</button><button data-aura-voice="contact">“Contact my daughter”</button><button data-aura-voice="stop">Cancel</button></div></div><button class="aura-app-primary" data-aura-demo="day">Adjust my lighting ↗</button><button class="aura-app-secondary" data-aura-voice="contact">Contact Elena</button><div class="aura-contact-confirm" hidden><p>Send Elena a request to talk?</p><button class="aura-app-primary" data-aura-voice="send">Confirm request</button><button class="aura-app-secondary" data-aura-voice="cancel">Cancel</button></div><p class="aura-contact-status" aria-live="polite"></p><p class="aura-demo-feedback" id="aura-day-feedback" aria-live="polite">Your home, at your pace.</p></div><nav class="aura-app-nav" aria-label="Dashboard preview"><b>⌂ Home</b><span>◷ Routine</span><span>◉ Sharing</span></nav></div><h4>01 / Everyday agency</h4><p>Optional voice, direct touch controls, and a confirmed request to a trusted contact.</p></article><article class="aura-screen-column"><div class="aura-phone aura-phone-night"><div class="aura-phone-status"><span>02:13</span><span>••• ▰</span></div><div class="aura-phone-body"><div class="aura-app-brand">aura <span>NIGHT MODE</span></div><div class="aura-moon" aria-hidden="true">☾</div><small class="aura-night-time">A QUIETER KIND OF SUPPORT</small><h4>A little more<br>light, Maria?</h4><p>Make the hallway easier to see.<br>You’re in control.</p><div class="aura-ui-card"><label for="aura-light">Hallway brightness <output id="aura-brightness">30%</output></label><input id="aura-light" type="range" min="10" max="100" value="30" step="10"></div><button class="aura-app-primary" data-aura-demo="light">Yes please</button><button class="aura-app-secondary" data-aura-demo="decline">Not right now</button><p class="aura-demo-feedback" id="aura-night-feedback" aria-live="polite">No change until you choose.</p></div></div><h4>02 / Support by invitation</h4><p>A single decision, a large control, and equal permission to decline.</p></article><article class="aura-screen-column"><div class="aura-phone"><div class="aura-phone-status"><span>09:41</span><span>••• ▰</span></div><div class="aura-phone-body"><div class="aura-app-brand">aura <span>TRUSTED CIRCLE</span></div><h4>Closer, even<br>from afar.</h4><div class="aura-family-person"><span class="aura-avatar">M</span><div><h5>Maria’s home</h5><small>Shared with you by Maria</small></div></div><div class="aura-ui-card"><small>LATEST SHARED UPDATE · 08:42</small><h5>Morning check-in</h5><p>“Looking forward to the garden.”</p><span class="aura-ui-tag">Shared by Maria</span></div><div class="aura-ui-row"><h5>Sharing boundaries</h5><span>◈</span></div><div class="aura-notification-feature"><small>FAMILY & CAREGIVER NOTIFICATIONS</small><p>Receive agreed alerts and requests for help.</p><span>Sharing managed by Maria</span></div><div class="aura-permission">Personal check-ins <b>Shared</b></div><div class="aura-permission">Room activity <b>Private</b></div><div class="aura-permission">Health information <b>Private</b></div><button class="aura-app-primary" data-aura-demo="checkin">Request a check-in</button><p class="aura-demo-feedback" id="aura-family-feedback" aria-live="polite">Maria chooses when to respond.</p></div><div class="aura-app-nav"><b>◉ Circle</b><span>◷ Updates</span><span>⚙ Settings</span></div></div><h4>03 / Connection with boundaries</h4><p>Visible provenance and permissions replace an unexplained health or risk score.</p></article></div></section>`}
function auraEcoCopy(i){return [['Maria / the decision-maker','Adjusts the environment, chooses prompts, and controls permissions. Support begins with her preferences.','CONTROL → Home settings and sharing choices'],['The adaptive home','Lighting and proposed environmental sensing form the domestic layer. Residents need understandable controls and a manual override.','ASSISTANCE → Resident-approved environmental changes'],['Elena / trusted family','Receives the updates Maria has chosen to share. A family relationship does not imply access to every routine or health detail.','CONNECTION → Selected updates, with timestamps'],['Care network','A proposed role for agreed support and escalation, with responsibilities defined separately from family access.','SUPPORT → Explicitly agreed contact arrangements'],['Service provider','Installs and maintains the home layer, explains permissions, and supports faults. Technical access should be separate from personal information.','OPERATIONS → Setup, maintenance, and repair']][i]}
function auraEcoPanel(i){const a=auraEcoCopy(i);return `<small>${a[2]}</small><h4>${a[0]}</h4><p>${a[1]}</p>`}
function auraEcosystem(){return `<div class="aura-ecosystem"><div class="aura-eco-map" aria-label="Explore proposed AURA ecosystem"><div class="aura-eco-line" aria-hidden="true"></div>${['Maria','Adaptive home','Trusted family','Care network','Service provider'].map((n,i)=>`<button class="aura-eco-node eco-${i}" data-aura-eco="${i}" aria-pressed="${i===0}" aria-controls="aura-eco-panel"><small>${i===0?'AT THE CENTRE':'0'+i+' / CONNECTED ROLE'}</small><b>${n}</b><span>${['Choice & consent','Environmental support','Agreed updates','Defined assistance','Setup & maintenance'][i]}</span></button>`).join('')}</div><div class="aura-glass aura-eco-panel" id="aura-eco-panel" aria-live="polite">${auraEcoPanel(0)}</div></div><div class="aura-system-flow"><span>Sense locally</span><b>→</b><span>Interpret a pattern</span><b>→</b><span>Offer support</span><b>→</b><span>Resident chooses</span></div>`}
document.querySelector('#projectDetail').addEventListener('click',e=>{const b=e.target.closest('[data-aura-eco]');if(b){document.querySelectorAll('[data-aura-eco]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#aura-eco-panel').innerHTML=auraEcoPanel(Number(b.dataset.auraEco))}const d=e.target.closest('[data-aura-demo]');if(!d)return;const a=d.dataset.auraDemo;if(a==='day'){const out=document.querySelector('#aura-day-feedback');out.textContent=out.textContent.includes('warmer')?'Original lighting restored.':'Warmer lighting selected.';d.closest('.aura-phone').classList.toggle('aura-warm')}if(a==='light')document.querySelector('#aura-night-feedback').textContent='Hallway light set to '+document.querySelector('#aura-light').value+'%.';if(a==='decline')document.querySelector('#aura-night-feedback').textContent='No problem. Lighting stays unchanged.';if(a==='checkin')document.querySelector('#aura-family-feedback').textContent='Check-in requested · prototype only'});
document.querySelector('#projectDetail').addEventListener('input',e=>{if(e.target.id==='aura-light')document.querySelector('#aura-brightness').textContent=e.target.value+'%'});

function auraDonuts(items){return `<div class="aura-donut-grid">${items.map(([value,label],i)=>`<figure class="aura-glass aura-donut-card"><div class="aura-donut" style="--share:${value}%;--ring:${i===1?'#78b9a5':'#9c9bcc'}" role="img" aria-label="${value}%: ${label}. Figure from original project; sample and source not supplied."><span>${value}<small>%</small></span></div><figcaption>${label}</figcaption></figure>`).join('')}</div>`}
function auraResearchCharts(){return `<section class="aura-section aura-chart-section"><span class="aura-kicker">RESEARCH LANDSCAPE</span><h3>The bigger picture.<br>The everyday implications.</h3><p>I explored living arrangements, pressures on care, and attitudes toward technology to understand where support could fit into everyday life.</p><details class="aura-detail aura-chart-notes"><summary>Chart notes</summary><p>These figures are reproduced from the project boards. Supporting sources and participant counts are not available here, so the percentages should be read as exploratory project figures rather than established population findings. Bar values are approximate readings from the original artwork.</p></details><figure class="aura-glass aura-chart-card"><figcaption><span class="aura-kicker">01 / DEMOGRAPHIC TRENDS</span><h4>Older adults’ living arrangements</h4><p>Single-person and multi-person households · 2005–2025</p></figcaption><div class="aura-chart-legend"><span><i></i>Single-person</span><span><i></i>Multi-person</span></div><div class="aura-stack-chart"><div class="aura-y-axis"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div class="aura-stack-plot">${[[2005,33],[2010,37],[2015,40],[2020,44],[2025,44]].map(([year,value])=>`<div class="aura-stack-column"><div class="aura-stack" role="img" aria-label="${year}: approximately ${value}% single-person, ${100-value}% multi-person"><div style="height:${100-value}%" class="aura-stack-multi"><span>≈${100-value}%</span></div><div style="height:${value}%" class="aura-stack-single"><span>≈${value}%</span></div></div><b>${year}</b></div>`).join('')}</div></div><p class="aura-chart-reading"><b>Design lens</b> Consider the home as an environment for independent routines and access to support.</p></figure><figure class="aura-glass aura-chart-card"><figcaption><span class="aura-kicker">02 / SYSTEM PRESSURES & TECHNOLOGY</span><h4>Care is a system challenge.</h4><p>Intensity / maturity · 0–10 scale</p></figcaption><div class="aura-horizontal-chart">${[['Caregiver shortage',8.3],['Rising healthcare costs',7.8],['Institutional care capacity limit',6.6],['AI predictive health models emerging',6.1],['Smart device adoption among seniors',6.3]].map(([label,value])=>`<div class="aura-bar-row"><span>${label}</span><div class="aura-bar-track"><i style="width:${value*10}%"></i></div><b>≈${value}</b></div>`).join('')}<div class="aura-bar-axis" aria-hidden="true"><span>0</span><span>2</span><span>4</span><span>6</span><span>8</span><span>10</span></div></div><p class="aura-chart-reading"><b>Design lens</b> Installation, support, and care responsibilities belong alongside the interface. The original chart combines pressure and maturity measures; it is not a validated ranking.</p></figure><div class="aura-chart-heading"><span class="aura-kicker">03 / TECHNOLOGY PERCEPTION</span><h4>How support fits matters.</h4><p>Technology-perception figures from the project exploration.</p></div>${auraDonuts([[52,'Forget or stop wearing health-tracking devices after 3 months.'],[69,'Prefer environmental sensing (floor, lighting) over wearables.'],[81,'Want technology to be “invisible” and non-medical.']])}<div class="aura-chart-heading"><span class="aura-kicker">04 / BEHAVIOURAL INSIGHTS</span><h4>Independence, confidence, control.</h4><p>Behavioural figures from the project exploration.</p></div>${auraDonuts([[72,'Prefer living independently even with minor health risks.'],[58,'Have experienced at least one minor fall or near-fall.'],[64,'Fear loss of autonomy more than physical injury.']])}</section>`}
function auraProductConcept(){return `<section class="aura-section aura-solution"><span class="aura-kicker">THE SOLUTION / CONFIDENCE AT HOME</span><h3>A familiar home.<br>A voice away from support.</h3><p>AURA is a voice-assisted home companion for night-time confidence and connection, with discreet home integration. Voice is optional; clear touch controls offer the same essential actions.</p><div class="aura-decision-cards">${[['01','Keep home familiar.','Participants wanted to stay home without very visible changes.','Subtle lighting integration and warm domestic materials bring support into the spaces people already know.'],['02','Make nights easier to navigate.','Night-time was a recurring source of insecurity.','“AURA, turn on the hallway light.” An optional voice command and a large touch control offer two ways to adjust the environment.'],['03','Make reaching someone straightforward.','Some participants wondered who would help if an accident happened.','“Contact my daughter.” Confirm the intended person, then show whether a request is pending, delivered, or unsuccessful.'],['04','Make connection an everyday action.','Loneliness came up alongside physical safety.','Offer an easy way to start a conversation with a trusted person, without requiring a safety concern.']].map(([n,title,heard,response])=>`<article class="aura-glass"><span class="aura-kicker">${n} / CORE EXPERIENCE</span><h4>${title}</h4><div><small>PARTICIPANT THEME · PARAPHRASED</small><p>${heard}</p></div><div><small>DESIGN RESPONSE</small><p>${response}</p></div></article>`).join('')}</div><div class="aura-game-insight"><span class="aura-kicker">DESIGN INTENT</span><h4>Feels like a home, not a robot.</h4><p>Familiar surroundings. Optional voice. Visible listening and sharing states. A touch alternative for every essential action.</p></div><div class="aura-care-notifications aura-glass"><span class="aura-kicker">CONNECTED CARE</span><h4>The right update, to the right person.</h4><p>Family and caregiver notifications prioritise agreed alerts and requests for help. The resident chooses recipients and sharing permissions. Routine activity stays private unless they choose otherwise.</p><p>Delivery status is separate from a person’s response: a delivered request does not mean help is on the way.</p></div><div class="aura-product-path">${[['01','Choose','Voice or touch'],['02','Confirm','Action and recipient'],['03','Understand','Listening, delivery, and sharing status'],['04','Stay in control','Cancel, retry, or use touch']].map(([n,title,body])=>`<article class="aura-glass"><small>${n}</small><h4>${title}</h4><p>${body}</p></article>`).join('')}</div><details class="aura-detail"><summary>Future explorations: predictive sensing and kitchen support</summary><p>The wider concept explores sensors → edge AI → pattern detection → environmental adjustment. Fall-risk prediction, pressure-sensitive flooring, and kitchen-specific safety support require separate feasibility and validation work. They sit beyond the core voice, lighting, and connection experience.</p></details></section>`}

document.querySelector('#projectDetail').addEventListener('click',e=>{const b=e.target.closest('[data-aura-jump]');if(!b)return;const t=document.querySelector(b.dataset.auraJump),d=document.querySelector('#projectDialog');if(t)d.scrollTo({top:d.scrollTop+t.getBoundingClientRect().top-d.getBoundingClientRect().top-20,behavior:reducedMotion.matches||data.motionPaused?'instant':'smooth'})});

function auraEvidenceBridge(){const decisions=[['01','The environment is part of independence.','WHO describes functional ability as the interaction between a person’s capacities and their environment.','AURA considers the room, lighting, and controls together, rather than treating the phone as the whole product.','Spatial concept + resident dashboard','https://www.who.int/news-room/questions-and-answers/item/healthy-ageing-and-functional-ability','WHO · Healthy ageing and functional ability'],['02','Choice belongs with the resident.','WHO’s age-friendly guidance emphasises varied needs and respect for older people’s decisions.','The night-time prompt includes “Not right now”; the family view separates shared check-ins from private information.','Night-time choice + sharing boundaries','https://www.who.int/teams/social-determinants-of-health/demographic-change-and-healthy-ageing/age-friendly-environments','WHO · Age-friendly environments'],['03','Adoption depends on trust and usability.','A published mixed-methods study reports concerns about privacy, perceived usefulness, and difficulty learning smart technologies.','The interface uses one clear action at a time and makes the origin of family updates visible.','Simple controls + “Shared by Maria”','https://www.jmir.org/2024/1/e45492','JMIR · SMART technology adoption, 2024'],['04','Environmental support is a grounded starting point.','WHO includes home assessment and modification among fall-prevention approaches for older adults.','AURA explores adjustable lighting as an environmental interaction. This does not establish that its AI predicts or prevents falls.','Lighting prototype; prediction remains exploratory','https://www.who.int/en/news-room/fact-sheets/detail/falls','WHO · Falls, 2021']];return `<section class="aura-section aura-evidence-bridge"><span class="aura-kicker">EVIDENCE → DESIGN DECISION</span><h3>A clear reason<br>behind each choice.</h3><p>Published evidence provides context for the concept. The connections below explain the design rationale; they do not imply these sources tested AURA.</p><div class="aura-verified-chart aura-glass"><div><span class="aura-kicker">EU POPULATION AGED 65+</span><h4>17% → 22%</h4><p>A five-percentage-point increase between 2005 and 2025.</p><a href="https://ec.europa.eu/eurostat/web/interactive-publications/demography-2026" target="_blank" rel="noopener">Eurostat · Demography of Europe 2026 ↗</a></div><div class="aura-verified-bars" role="img" aria-label="Share of EU population aged 65 and over: 17 percent in 2005 and 22 percent in 2025. Bar scale 0 to 100 percent."><div><span>2005</span><i style="--value:17%"></i><b>17%</b></div><div><span>2025</span><i style="--value:22%"></i><b>22%</b></div><small>Share of total EU population · 0–100% scale</small></div></div><div class="aura-decision-cards">${decisions.map(([n,title,evidence,decision,visible,url,source])=>`<article class="aura-glass"><span class="aura-kicker">${n} / DESIGN RATIONALE</span><h4>${title}</h4><div><small>PUBLISHED EVIDENCE</small><p>${evidence}</p><a href="${url}" target="_blank" rel="noopener">${source} ↗</a></div><div><small>AURA’S DESIGN RESPONSE</small><p>${decision}</p><strong>${visible}</strong></div></article>`).join('')}</div><div class="aura-evidence-scope"><span>Published research → context</span><span>Would-you-rather game → exploration</span><span>Interactive prototype → design outcome</span></div></section>`}

function auraParticipantInsights(){return `<section class="aura-section aura-participant-insights"><span class="aura-kicker">PARTICIPANT INSIGHTS / WOULD-YOU-RATHER CONVERSATIONS</span><h3>Keep home familiar.<br>Make support feel closer.</h3><p>Conversations with approximately 9–10 older adults surfaced four themes. The summaries below are paraphrased from my recollection of the sessions, rather than verbatim quotes or measured survey results.</p><div class="aura-decision-cards">${[['01','Home is where they want to stay.','Most participants did not want to leave home or introduce very visible changes.','I prioritised subtle integration into familiar spaces: warm materials, embedded infrastructure, and unobtrusive lighting.','DESIGN DIRECTION · SPATIAL INTEGRATION'],['02','Night-time feels less secure.','Many participants described feeling particularly insecure at night.','AURA’s night-time interaction offers a simple lighting adjustment, with an equally clear option to decline.','DESIGN RESPONSE · NIGHT-TIME LIGHTING'],['03','A kitchen accident raises a bigger question.','Some participants worried about an accident while cooking and who would be there to help.','This identifies an opportunity for kitchen support and an agreed response route. A kitchen-specific safety interaction is not yet part of the prototype.','OPPORTUNITY · KITCHEN SUPPORT'],['04','Loneliness is part of the problem.','Loneliness also came up in the conversations, alongside concerns about physical safety.','The trusted-circle concept offers a direct request to talk, with a named recipient and confirmation. Its effect on loneliness has not been tested.','DESIGN RESPONSE · TRUSTED CONNECTION']].map(([n,title,heard,response,status])=>`<article class="aura-glass"><span class="aura-kicker">${n} / PARTICIPANT THEME</span><h4>${title}</h4><div><small>WHAT I HEARD</small><p>${heard}</p></div><div><small>HOW AURA RESPONDS</small><p>${response}</p><strong>${status}</strong></div></article>`).join('')}</div><div class="aura-game-insight"><span class="aura-kicker">THE STRATEGIC TAKEAWAY</span><h4>Bring support into the home people already love.</h4><p>These conversations supported seamless home integration as a design direction. They also broadened the focus from physical safety to reassurance, everyday confidence, and human connection.</p></div></section>`}

document.querySelector('#projectDetail').addEventListener('click',e=>{const b=e.target.closest('[data-aura-voice]');if(!b)return;const root=document.querySelector('.aura-screen-section'),status=root.querySelector('.aura-voice-status'),commands=root.querySelector('.aura-voice-commands'),toggle=root.querySelector('[data-aura-voice="start"]'),confirmation=root.querySelector('.aura-contact-confirm'),contact=root.querySelector('.aura-contact-status');const stop=()=>{commands.hidden=true;toggle.setAttribute('aria-pressed','false');status.textContent='Microphone off'};switch(b.dataset.auraVoice){case 'start':if(toggle.getAttribute('aria-pressed')==='true'){stop();return}toggle.setAttribute('aria-pressed','true');commands.hidden=false;status.textContent='Listening preview · choose a sample command. No microphone is used.';break;case 'lamp':stop();status.textContent='Understood: hallway light on · simulation';root.querySelector('#aura-day-feedback').textContent='Hallway light on · prototype only';break;case 'contact':stop();confirmation.hidden=false;contact.textContent='Nothing sent. Confirm Elena as the recipient.';break;case 'send':confirmation.hidden=true;contact.innerHTML='Request delivered · simulated. Awaiting Elena’s response.<button class="aura-app-secondary" data-aura-voice="failure">Preview delivery failure</button>';break;case 'failure':contact.innerHTML='Not delivered · simulated. Try again or contact Elena another way.<button class="aura-app-secondary" data-aura-voice="contact">Try again</button>';break;case 'cancel':confirmation.hidden=true;contact.textContent='Cancelled. Nothing sent.';stop();break;default:stop()}});

const occasioStart=hqGluvia.length;
const occasioAssets=['cover','problem','journey','identity','inspiration','web','mobile-discover','mobile-intro','mobile-form'].map(n=>({src:'assets/occasio/'+n+'.png',title:'OCCASIO — '+n.replaceAll('-',' ')}));hqGluvia.push(...occasioAssets);
const occasioProject={id:'occasio',title:'OCCASIO',subtitle:'Discover the occasion. Create the celebration.',category:'UI / UX',year:'Concept project',theme:'orbit',image:'',role:'UI / UX · Visual identity · Web & mobile',challenge:'Connect public event discovery with private celebration planning.',approach:'Two complementary experiences under one expressive visual identity.',outcome:'A landing website and mobile interface concept.',concept:true};defaults.projects.splice(2,0,structuredClone(occasioProject));if(!data.projects.some(p=>p.id==='occasio')){data.projects.splice(2,0,structuredClone(occasioProject));try{localStorage.setItem(key,JSON.stringify(data))}catch{}}
function occasionBoard(i,caption){return `<figure class="oc-board"><button data-hq="${occasioStart+i}" aria-label="Enlarge ${occasioAssets[i].title}"><img src="${occasioAssets[i].src}" alt="${caption}" loading="lazy"></button><figcaption>${caption}<span>View detail ↗</span></figcaption></figure>`}
function ocMobile(i){const n=[7,6,8][i];return `${occasionBoard(n,['Welcome and event selection','Private celebrations and service discovery','Event introduction and enquiry form'][i])}<p>${['An expressive welcome introduces the brand before moving into event choices.','Service categories bring weddings, birthdays, and corporate events into a shared discovery pattern.','A structured enquiry collects the details needed to begin planning a celebration.'][i]}</p>`}
function occasioView(){return `<article class="oc-case"><header class="oc-hero"><div><span class="oc-kicker">KRITIKA / UI & UX / WEB + MOBILE CONCEPT</span><h2>OCCASIO<span>Plans made<br><em>effortless.</em></span></h2><p>Discover public events.<br>Create private celebrations.</p><div class="oc-tags"><span>Experience design</span><span>Visual identity</span><span>Two platforms</span></div></div><img src="assets/occasio/cover.png" alt="OCCASIO mascot and phone cover"></header><section class="oc-section"><span class="oc-kicker">01 / ONE BRAND, TWO INTENTIONS</span><h3>Some occasions you find.<br>Others, you create.</h3><div class="oc-two"><article><small>THE WEBSITE</small><h4>Find your next experience.</h4><p>A public-event landing experience for concerts, festivals, markets, and comedy. Event imagery, dates, and locations introduce the possibilities.</p></article><article><small>THE MOBILE APP</small><h4>Start your own celebration.</h4><p>A private-event planning concept for weddings, birthdays, and corporate gatherings, from choosing a service to organising event details, guests, and requirements.</p></article></div></section><section class="oc-section oc-blue"><span class="oc-kicker">02 / PROBLEM → SOLUTION</span><h3>Four frictions.<br>Four design responses.</h3><p>The project brief frames four opportunities across discovering public events and organising private celebrations.</p><div class="oc-problem-grid">${[['Overwhelming event discovery','Long, uncurated listings make it difficult to find relevant experiences.','Curated event discovery','Location, mood, trending picks, and weekend highlights create clearer starting points.'],['Fragmented planning tools','Coordinating venues, caterers, decorators, and photographers across tools adds planning effort.','An integrated planning hub','Bring event details, services, guest lists, budgets, and timelines into one proposed workspace.'],['Weak social integration','Inviting friends and coordinating shared plans can feel disconnected from discovery.','Social and collaborative features','The concept proposes shared events, invitations, split costs, and collaborative planning.'],['Low emotional engagement','A purely functional experience can miss the excitement of an occasion.','An expressive design system','Bold imagery, a friendly mascot, and different visual rhythms for discovery and planning build anticipation.']].map(([problem,detail,solution,response],i)=>`<article><span class="oc-kicker">0${i+1} / DESIGN OPPORTUNITY</span><div><small>PROBLEM</small><h4>${problem}</h4><p>${detail}</p></div><div><small>SOLUTION DIRECTION</small><h4>${solution}</h4><p>${response}</p></div></article>`).join('')}</div><p class="oc-small">Proposed product scope; collaboration, payments, and budget-management flows are part of the wider concept scope.</p></section><section class="oc-section"><span class="oc-kicker">03 / USER EVENT JOURNEY</span><h3>From the first spark<br>to the shared memory.</h3><p>The intended public-event journey spans five stages. Each stage connects a user action with the information or support the experience needs to provide.</p><div class="oc-journey-detailed">${[['Discover','Find something worth going to.',['Location-based browsing','Category filters','Mood-based recommendations','Trending events']],['Select','Decide whether it feels right.',['Event details','Artist lineup','Venue information','Ticket pricing tiers','Reviews and ratings']],['Book','Turn interest into a plan.',['Seat selection where applicable','Ticket quantity','Discount codes','Secure payment']],['Attend','Arrive ready for the experience.',['QR-based digital tickets','Event reminders','Calendar integration','Entry validation']],['Share','Bring others into the memory.',['Share tickets or event pages','Invite friends','Post attendance on social media','Leave reviews']]].map(([name,goal,items],i)=>`<article><span class="oc-step-number">0${i+1}</span><div><h4>${name}</h4><p>${goal}</p><ul>${items.map(t=>`<li>${t}</li>`).join('')}</ul></div></article>`).join('')}</div><p class="oc-small">Journey concept · the current interface work focuses on discovery and the start of planning.</p></section><section class="oc-section oc-identity"><span class="oc-kicker">04 / A BRAND WITH A SPARK</span><h3>A little character.<br>A lot of excitement.</h3><p>The friendly blue mascot expresses the anticipation before an event. Electric blue and lime accents give the interface an energetic, recognisable identity.</p>${occasionBoard(3,'Mascot and logo concept.')}${occasionBoard(4,'The spark of anticipation behind the mascot.')}</section><section class="oc-section"><span class="oc-kicker">05 / THE WEB EXPERIENCE</span><h3>An invitation<br>to go out.</h3><p>Event discovery leads into the brand story, artists, and gallery before the contact section. Explore the landing-page design.</p><div class="oc-browser"><div><span>● ● ●</span><b>OCCASIO / WEBSITE DESIGN</b></div><div class="oc-web-scroll" tabindex="0" role="region" aria-label="Scrollable OCCASIO landing page"><img src="assets/occasio/web.png" alt="OCCASIO landing page with event cards, artists, gallery, and enquiry"></div></div><p class="oc-small">Interface concept · sample event listings and testimonials.</p><button class="oc-button" data-hq="${occasioStart+5}">Inspect full landing page ↗</button></section><section class="oc-section oc-mobile"><span class="oc-kicker">06 / THE MOBILE EXPERIENCE</span><h3>Your celebration.<br>In your hands.</h3><div class="oc-gallery-links" aria-label="Jump to mobile mockups"><button data-oc-jump="oc-mobile-welcome">Welcome & events ↓</button><button data-oc-jump="oc-mobile-services">Service discovery ↓</button><button data-oc-jump="oc-mobile-planning">Planning details ↓</button></div><div class="oc-mobile-group" id="oc-mobile-welcome"><small>01 / WELCOME & EVENT SELECTION</small><h4>Meet the brand. Explore the possibilities.</h4><p>The mascot-led introduction establishes the tone, followed by a selection of events.</p>${occasionBoard(7,'Welcome and event selection.')}</div><div class="oc-mobile-group" id="oc-mobile-services"><small>02 / SERVICE DISCOVERY</small><h4>A starting point for your celebration.</h4><p>Featured services organise weddings, birthdays, and corporate gatherings. The companion introduction sets up the next step.</p><div class="oc-clean-phones"><figure><div class="oc-phone-export oc-phone-services"><img src="assets/occasio/service-phone.png" alt="OCCASIO featured services phone screen"></div><figcaption>Featured services</figcaption></figure><figure class="oc-intro-composition"><div class="oc-phone-export oc-phone-intro"><img src="assets/occasio/intro-phone.png" alt="OCCASIO celebration introduction phone screen"></div><figcaption class="oc-phone-caption-card"><span>FROM IDEA TO OCCASION</span><strong>Your celebration.<br>Your way.</strong><p>A welcoming first step toward a personal event.</p></figcaption></figure></div></div><div class="oc-mobile-group" id="oc-mobile-planning"><small>03 / EVENT PLANNING</small><h4>Bring the practical details together.</h4><p>The planning screen brings event type, date, location, guest names, and required services into one view, with a budget-overview tab visible in the design.</p>${occasionBoard(8,'Planning introduction and event-details form.')}</div></section><section class="oc-section"><span class="oc-kicker">07 / DESIGN OUTCOME</span><h3>One identity.<br>Two ways to celebrate.</h3><p>OCCASIO brings a public-event website and private-event mobile concept together through a distinctive mascot, vivid colour, and consistent visual language.</p><div class="oc-two"><article><small>WEBSITE</small><h4>Inspire discovery.</h4><p>Expressive imagery paired with event information and clear entry points.</p></article><article><small>MOBILE</small><h4>Begin the plan.</h4><p>Service discovery, event details, guest lists, and requirements for a personal occasion.</p></article></div></section><footer class="oc-footer"><span class="oc-kicker">OCCASIO / BY KRITIKA</span><h3>Good plans.<br><em>Great memories.</em></h3><button data-case-top>Back to the start ↑</button><button data-case-close>Explore more work ↗</button></footer></article>`}
document.querySelector('#projectDetail').addEventListener('click',e=>{const b=e.target.closest('[data-oc-mobile]');if(!b)return;document.querySelectorAll('[data-oc-mobile]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));document.querySelector('#oc-mobile-panel').innerHTML=ocMobile(Number(b.dataset.ocMobile))});
render();function openOccasio(){if(location.hash==='#occasio'){const d=$('#projectDialog');if(d.open)d.close();document.querySelector('[data-id="occasio"]')?.click()}}addEventListener('hashchange',openOccasio);openOccasio();

document.querySelector('#projectDetail').addEventListener('click',e=>{const b=e.target.closest('[data-oc-jump]');if(!b)return;const t=document.getElementById(b.dataset.ocJump),d=document.querySelector('#projectDialog');d.scrollTo({top:d.scrollTop+t.getBoundingClientRect().top-d.getBoundingClientRect().top-20,behavior:reducedMotion.matches||data.motionPaused?'instant':'smooth'})});

hqGluvia.push({src:"assets/occasio/service-phone.png",title:"OCCASIO featured services"},{src:"assets/occasio/intro-phone.png",title:"OCCASIO celebration introduction"});

